def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_def = 0
    for _, o in history:
        if o == 'D':
            opp_def += 1
    opp_rate = opp_def / n

    if opp_rate > 0.5:
        return 'D'

    last_me, last_opp = history[-1]

    if last_opp == 'D':
        recent_opp_def = 0
        start = max(0, n - 5)
        for i in range(start, n):
            if history[i][1] == 'D':
                recent_opp_def += 1
        if recent_opp_def >= 2 or opp_rate > 0.2:
            return 'D'
        return 'C'

    if last_me == 'D':
        return 'C'

    if n < 5:
        return 'C'
    if n == 5:
        return 'D'
    if n == 6:
        return 'C'

    retaliations = 0
    forgiveness = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            if history[i + 1][1] == 'D':
                retaliations += 1
            else:
                forgiveness += 1

    if retaliations > forgiveness:
        return 'C'

    diff = forgiveness - retaliations
    p = min(0.5, 0.1 * diff)

    if rng.random() < p:
        return 'D'
    return 'C'
